#include <iostream>
#include <stack>
#include <string_view>
int evaluate_rpn(std::initializer_list<std::string_view> tokens) {
    std::stack<int> values;
    for (auto token : tokens) {
        if (token == "+" || token == "*") {
            if (values.size() < 2) throw std::runtime_error("missing operand");
            int right = values.top(); values.pop(); int left = values.top(); values.pop();
            values.push(token == "+" ? left + right : left * right);
        } else values.push(std::stoi(std::string(token)));
    }
    if (values.size() != 1) throw std::runtime_error("invalid expression");
    return values.top();
}
int main() { std::cout << evaluate_rpn({"3", "4", "+", "2", "*"}) << '\n'; }
